package com.projectdark.mobile;
import android.content.*;import android.graphics.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SystemsV215Test {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{"project_dark_f5m_v1","project_dark_skill_test_v1"})c.getSharedPreferences(n,0).edit().clear().commit();F5mSaveStore.install(c);}
 @Test public void crossing99RetainsAllThresholdsAndOverflowWithoutCountingTwice(){long sum=0;for(int lv=1;lv<99;lv++)sum+=LevelExpCurve.requiredForNext(lv);RpgProgressionState r=new RpgProgressionState();r.restoreProgression(1,0);r.grantAdaptedReward(sum+123,0);assertEquals(99,r.normalLevel().intValue());assertEquals(sum+123,r.normalExp().longValue());assertEquals(sum+123,CampaignProgress.earnedExp(r));r.grantAdaptedReward(100,0);assertEquals(sum+223,r.normalExp().longValue());r.grantAdaptedReward(Long.MAX_VALUE,0);assertEquals(TempleGrowthPolicy.EXP_CAP,r.normalExp().longValue());}
 @Test public void legacy99MigrationCommitsOnceEvenWithoutLaterAutosaveAndPreservesOvercap(){SharedPreferences p=c.getSharedPreferences("project_dark_f5m_v1",0);RpgProgressionState r=new RpgProgressionState();r.restoreProgression(99,1234);F5mSaveStore.saveRewardsActive(r);p.edit().remove("exp_retained_v215").commit();for(int i=0;i<3;i++){F5mSaveStore.install(c);RpgProgressionState restored=new RpgProgressionState();F5mSaveStore.restoreRewardsActive(restored);assertTrue(F5mSaveStore.writable());assertEquals(LevelExpCurve.totalTo99()+1234,restored.normalExp().longValue());assertTrue(p.getBoolean("exp_retained_v215",false));}p.edit().remove("exp_retained_v215").putLong("normal_exp",5_000_000_000L).commit();F5mSaveStore.install(c);r=new RpgProgressionState();F5mSaveStore.restoreRewardsActive(r);assertEquals(5_000_000_000L,r.normalExp().longValue());}
 @Test public void legacyOrnamentWingsBecomeOneExclusiveWingWithoutDeletingOwnedItems()throws Exception{RpgProgressionState r=((RuntimeState)TownInteriorTest.field(new GameView(c),"state")).rpg();List<String> wings=new ArrayList<>();for(RpgProgressionState.ItemDefinition d:r.canonicalItemDefinitions().values())if("날개".equals(d.equipSlot))wings.add(d.itemId);assertEquals(18,wings.size());Map<String,Integer> owned=new LinkedHashMap<>(r.inventory());Map<String,String> old=new LinkedHashMap<>();old.put("장식",wings.get(0));old.put(RpgProgressionState.SECOND_ORNAMENT_SLOT,wings.get(1));assertTrue(r.restoreOwnedItems(owned,old));assertEquals(owned,r.inventory());assertEquals(1,r.equipment().size());assertEquals(wings.get(0),r.equipment().get("날개"));r.enableEquipmentSandbox(true);assertEquals(RpgProgressionState.EquipResult.EQUIPPED,r.equip(wings.get(1)));assertEquals(wings.get(1),r.equipment().get("날개"));assertEquals(owned,r.inventory());F5mSaveStore.saveRewardsActive(r);F5mSaveStore.install(c);RpgProgressionState restored=new RpgProgressionState();F5mSaveStore.restoreRewardsActive(restored);assertEquals(r.equipment(),restored.equipment());assertEquals(owned,restored.inventory());}
 CharacterRenderer.Pose pose(CharacterVisualBinding b,CharacterRenderer.Direction d,CharacterRenderer.State state){return new CharacterRenderer.Pose(80,104,d,state,0,.5f,1,false,b.equipmentVisualRef(),b.weaponVisualRef(),null,CharacterRenderer.EffectFamily.NONE,AnimationAction.SWING);}
 int delta(Bitmap a,Bitmap b){int n=0;for(int y=0;y<a.getHeight();y++)for(int x=0;x<a.getWidth();x++)if(a.getPixel(x,y)!=b.getPixel(x,y))n++;return n;}
 void save(Bitmap b,String name)throws Exception{File f=new File("build/reports/horror-v179/v215/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}}
 @Test public void allNamedShieldsAndWingsRenderInFourDirectionsFromActualEquippedBindings()throws Exception{
  RpgProgressionState r=new RpgProgressionState();r.enableEquipmentSandbox(true);CharacterRenderer renderer=new CharacterRenderer(c);SkillBodyRenderer skill=new SkillBodyRenderer(c,new SkillPresentationCatalog(c));List<String> ids=new ArrayList<>();for(RpgProgressionState.ItemDefinition d:r.canonicalItemDefinitions().values())if("날개".equals(d.equipSlot)||d.itemId.startsWith("IT_SHIELD_"))ids.add(d.itemId);assertEquals(32,ids.size());Bitmap sheet=Bitmap.createBitmap(1280,ids.size()*160,Bitmap.Config.ARGB_8888);Canvas sc=new Canvas(sheet);sc.drawColor(0xff383128);Paint text=new Paint();text.setColor(Color.WHITE);text.setTextSize(10);CharacterRenderer.Direction[] dirs={CharacterRenderer.Direction.NE,CharacterRenderer.Direction.NW,CharacterRenderer.Direction.SE,CharacterRenderer.Direction.SW};
  for(int row=0;row<ids.size();row++){String id=ids.get(row);assertTrue(r.restoreOwnedItems(r.inventory(),Collections.emptyMap()));CharacterVisualBinding bare=CharacterVisualBinding.from(r);assertEquals(id,RpgProgressionState.EquipResult.EQUIPPED,r.equip(id));CharacterVisualBinding worn=CharacterVisualBinding.from(r);RpgProgressionState.ItemDefinition def=r.itemDefinitions().get(id);assertTrue(worn.equipmentVisualRef().contains(def.appearanceId));if("날개".equals(def.equipSlot))assertTrue(worn.equipmentVisualRef().contains(WingShieldV215.front(def.appearanceId)));sc.drawText(def.name,5,row*160+15,text);
   for(int d=0;d<4;d++)for(int action=0;action<2;action++){Bitmap plain=Bitmap.createBitmap(160,144,Bitmap.Config.ARGB_8888),actual=Bitmap.createBitmap(160,144,Bitmap.Config.ARGB_8888);CharacterRenderer.State state=action==0?CharacterRenderer.State.IDLE:CharacterRenderer.State.ATTACK;renderer.draw(new Canvas(plain),pose(bare,dirs[d],state));renderer.draw(new Canvas(actual),pose(worn,dirs[d],state));assertTrue(id+dirs[d]+state+" worn pixels",delta(plain,actual)>8);sc.drawBitmap(actual,(action*4+d)*160,row*160+16,null);plain.eraseColor(Color.TRANSPARENT);actual.eraseColor(Color.TRANSPARENT);String motion=action==0?"IDLE":"SWING";assertTrue(skill.draw(new Canvas(plain),pose(bare,dirs[d],state),"wm001",motion,.5f));skill.prepare(worn.equipmentVisualRef(),worn.weaponVisualRef());assertTrue(skill.draw(new Canvas(actual),pose(worn,dirs[d],state),"wm001",motion,.5f));assertTrue(id+dirs[d]+" female "+motion,delta(plain,actual)>8);plain.recycle();actual.recycle();}
  }save(sheet,"all-shields-wings-idle-contact");sheet.recycle();
 }
 @Test public void actualWindowsShowTwelveFiltersNewWingSlotAndNumericExp()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().enableEquipmentSandbox(true);s.rpg().restoreProgression(99,4_123_456_789L);assertEquals(RpgProgressionState.EquipResult.EQUIPPED,s.rpg().equip("USER_ITEM_20261018_R00689"));assertEquals(RpgProgressionState.EquipResult.EQUIPPED,s.rpg().equip("IT_SHIELD_DEATHKNIGHT"));ItemWindowReferenceTest.tap(v,830,28);capture(v,"equipment-wing-shield");ItemWindowReferenceTest.tap(v,ItemWindow.equipmentStats().centerX(),ItemWindow.equipmentStats().centerY());assertTrue((Boolean)TownInteriorTest.field(v,"statsOpen"));capture(v,"stats-held-exp");ItemWindowReferenceTest.tap(v,911,91);ItemWindowReferenceTest.tap(v,742,28);assertTrue((Boolean)TownInteriorTest.field(v,"inventoryOpen"));ItemWindow w=TownInteriorTest.field(v,"itemWindow");assertEquals(10,ItemWindow.category(w.find(s.rpg(),"IT_REAGENT_KOMADIUM"),s.rpg()));assertEquals(14,ItemWindow.category(w.find(s.rpg(),"IT_NA_FOOD_293294_00"),s.rpg()));assertEquals(14,ItemWindow.category(w.find(s.rpg(),"IT_RECALL_MILLES"),s.rpg()));assertArrayEquals(new String[]{"전체","무기","모자","옷","신발","각반","반지","목걸이","벨트","날개","시약","방패","귀걸이","장갑","기타"},ItemWindow.FILTERS);for(int i=0;i<ItemWindow.FILTERS.length;i++){RectF tab=ItemWindow.filterTab(i);ItemWindowReferenceTest.tap(v,tab.centerX(),tab.centerY());assertEquals(i,w.filter);capture(v,"inventory-"+i);}assertEquals("날개",ItemWindow.SLOTS[15]);}
 @Test public void heldJoystickCrossesTheDoorWithoutStoppingOnAnExactTile()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);v.setSkillTestMode(false);com.projectdark.mobile.world.TownInteriorDef hub=com.projectdark.mobile.world.TownInteriorDef.forMap("milles_interior_temple_hub");TownInteriorTest.enter(v,hub);RuntimeState state=TownInteriorTest.field(v,"state");com.projectdark.mobile.world.WorldRuntimeAdapter w=TownInteriorTest.field(v,"reagentShopAdapter");state.player().x=com.projectdark.mobile.world.TownInteriorDef.x(22,25);state.player().y=com.projectdark.mobile.world.TownInteriorDef.y(22,25);w.snapCameraToPlayer();android.view.MotionEvent down=android.view.MotionEvent.obtain(0,0,android.view.MotionEvent.ACTION_DOWN,110,374,0);v.onTouchEvent(down);down.recycle();android.view.MotionEvent move=android.view.MotionEvent.obtain(0,16,android.view.MotionEvent.ACTION_MOVE,70,354,0);v.onTouchEvent(move);move.recycle();TownInteriorTest.tick(v,50);assertEquals("milles_interior_temple_seo",state.currentMapId());capture(v,"held-joystick-door");}
 @Test public void floatingBladePackedContactFramesNeverBorrowTheOtherFacing(){EquipmentVisualRegistry r=new EquipmentVisualRegistry(c);for(int i=0;i<4;i++){assertEquals(i>=2,r.get("mg332").registration.action(i)!=null);assertEquals(i<2,r.get("mc332").registration.action(i)!=null);}}
 void capture(GameView v,String n)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));save(b,n);b.recycle();}
}
